import './styles.css'
const root = document.getElementById('root')
root.innerHTML = '<main><h1>Counter</h1><time></time><button id=increment>Add</button><output>0</output></main>'
document.querySelector('time').textContent = new Date().toISOString().slice(0, 10)
let count = 0
document.querySelector('button').onclick = () => { document.querySelector('output').textContent = String(++count) }
